// @generated by tools/gen_assets.py from the original job_finder.py
pub const REPORT_CSS: &str = r#"
:root{--bg:#EDF1F4;--surface:#FFFFFF;--ink:#10202E;--muted:#556677;--line:#D3DCE3;--chip:#E2EAF0;--accent:#0E6A70;--warn:#8A5A00;--good:#17663A}
:root[data-theme=dark]{--bg:#0C1520;--surface:#132130;--ink:#E5EDF3;--muted:#93A5B5;--line:#243749;--chip:#1C2F42;--accent:#52C4BF;--warn:#E3B04B;--good:#6FD39A}
@media (prefers-color-scheme:dark){:root:not([data-theme=light]){--bg:#0C1520;--surface:#132130;--ink:#E5EDF3;--muted:#93A5B5;--line:#243749;--chip:#1C2F42;--accent:#52C4BF;--warn:#E3B04B;--good:#6FD39A}}
*{box-sizing:border-box}
html{scroll-padding-top:5rem}
body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 "Segoe UI",system-ui,-apple-system,Tahoma,"Noto Sans Arabic",sans-serif}
a{color:var(--accent)}
:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
header.top{max-width:60rem;margin:0 auto;padding:2.5rem 1.25rem 1rem}
header.top h1{font:600 2.1rem/1.15 Georgia,"Iowan Old Style","Times New Roman",serif;margin:0 0 .5rem;letter-spacing:-.01em}
header.top p{margin:.2rem 0;color:var(--muted);max-width:44rem}
.funnel{display:flex;flex-wrap:wrap;gap:.4rem 1.2rem;margin-top:1rem;font-size:.9rem;color:var(--muted)}
.funnel b{color:var(--ink);font-weight:650}
.bar{position:sticky;top:0;z-index:5;background:var(--bg);border-bottom:1px solid var(--line)}
.bar .in{max-width:60rem;margin:0 auto;padding:.7rem 1.25rem;display:flex;flex-wrap:wrap;gap:.6rem;align-items:center}
.bar input,.bar select,.bar button{font:inherit;color:var(--ink);background:var(--surface);border:1px solid var(--line);border-radius:6px;padding:.45rem .65rem}
.bar input{flex:1 1 14rem;min-width:10rem}
.bar button{cursor:pointer}
.bar .shown{margin-inline-start:auto;color:var(--muted);font-size:.9rem}
main{max-width:60rem;margin:0 auto;padding:0 1.25rem 3rem}
section.day{margin-top:2rem}
section.day>h2{font:600 1.35rem/1.2 Georgia,"Iowan Old Style",serif;margin:0 0 .6rem;padding-bottom:.4rem;border-bottom:2px solid var(--ink);display:flex;justify-content:space-between;align-items:baseline;gap:1rem}
section.day>h2 span{font:400 .9rem "Segoe UI",system-ui,sans-serif;color:var(--muted)}
article.job{display:grid;grid-template-columns:6.5rem 1fr;gap:0 1.25rem;padding:1.2rem 0;border-bottom:1px solid var(--line)}
.when{color:var(--muted);font-size:.9rem;line-height:1.35}
.when strong{display:block;color:var(--ink);font-weight:600;font-size:1rem}
.main h3{margin:0 0 .15rem;font-size:1.12rem;line-height:1.3;font-weight:650}
.meta{margin:0 0 .5rem;color:var(--muted);font-size:.95rem}
.meta b{color:var(--ink);font-weight:600}
.chips{display:flex;flex-wrap:wrap;gap:.35rem;margin:.25rem 0 .55rem;padding:0;list-style:none}
.chips li{background:var(--chip);border-radius:999px;padding:.12rem .65rem;font-size:.82rem}
.chips li.warn{color:var(--warn)}
.why{margin:.2rem 0 .4rem;font-size:.92rem}
.how{margin:.6rem 0;padding:.75rem .95rem;background:var(--surface);border:1px solid var(--line);border-inline-start:4px solid var(--accent);border-radius:6px;max-width:44rem}
.how h4{margin:0 0 .35rem;font-size:.98rem}
.how p{margin:.2rem 0;font-size:.95rem;overflow-wrap:anywhere}
.how .none{color:var(--muted)}
.methods{list-style:none;margin:.5rem 0 0;padding:0;font-size:.95rem}
.methods li{padding:.18rem 0;overflow-wrap:anywhere}
.methods .k{display:inline-block;min-width:10rem;color:var(--muted)}
.flag{font-size:.78rem;padding:.04rem .5rem;border-radius:999px;background:var(--chip);margin-inline-start:.4rem;white-space:nowrap}
.flag.ok{color:var(--good)}
.flag.bad{color:var(--warn);white-space:normal}
.orig{margin:.3rem 0;font-size:.9rem}
details{margin:.25rem 0}
details summary{cursor:pointer;color:var(--accent);font-size:.92rem}
details .body{margin:.4rem 0 .2rem;padding:.6rem .8rem;background:var(--surface);border:1px solid var(--line);border-radius:6px;white-space:pre-wrap;font-size:.92rem;max-height:20rem;overflow:auto;max-width:42rem}
.empty{margin:3rem 0;padding:1.5rem;background:var(--surface);border:1px solid var(--line);border-radius:8px}
.empty h2{font:600 1.5rem Georgia,serif;margin:0 0 .5rem}
footer{max-width:60rem;margin:0 auto;padding:1rem 1.25rem 3rem;color:var(--muted);font-size:.85rem;border-top:1px solid var(--line)}
@media (max-width:42rem){article.job{grid-template-columns:1fr;gap:.4rem}.when strong{display:inline;margin-inline-end:.5rem}.methods .k{display:block;min-width:0}}
@media print{.bar{display:none}article.job{break-inside:avoid}}
"#;
pub const REPORT_JS: &str = r"
(function(){
  if(!document.getElementById('q'))return;
  var q=document.getElementById('q'),fs=document.getElementById('fsrc'),fl=document.getElementById('flang'),
      cnt=document.getElementById('shown'),jobs=[].slice.call(document.querySelectorAll('article.job')),
      days=[].slice.call(document.querySelectorAll('section.day'));
  function apply(){
    var t=q.value.trim().toLowerCase(),s=fs.value,l=fl.value,n=0;
    jobs.forEach(function(j){
      var ok=(!t||j.dataset.text.indexOf(t)>-1)&&(!s||j.dataset.source===s)&&(!l||j.dataset.lang===l);
      j.hidden=!ok; if(ok)n++;
    });
    days.forEach(function(d){d.hidden=!d.querySelector('article.job:not([hidden])')});
    cnt.textContent=n+' of '+jobs.length+' shown';
  }
  [q,fs,fl].forEach(function(e){e.addEventListener('input',apply)});
  var root=document.documentElement,btn=document.getElementById('theme');
  btn.addEventListener('click',function(){
    var dark=root.dataset.theme==='dark'||(!root.dataset.theme&&matchMedia('(prefers-color-scheme: dark)').matches);
    root.dataset.theme=dark?'light':'dark';
  });
  apply();
})();
";
